def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # The horizontal end-bars indicate vertical lanes: take their right-hand
    # half. Paint from both ends with the color of the scattered markers.
    bars = []
    for r in (0, h - 1):
        c = 0
        while c < w:
            color = grid[r][c]
            if c + 1 < w and grid[r][c + 1] == color:
                e = c + 1
                while e + 1 < w and grid[r][e + 1] == color:
                    e += 1
                # Ignore the uniform background run spanning most of an edge.
                if e - c + 1 < w // 2:
                    bars.append((r, c, e))
                c = e + 1
            else:
                c += 1
    colors = {}
    for row in grid:
        for v in row:
            colors[v] = colors.get(v, 0) + 1
    bg = max(colors, key=colors.get)
    marker = min((v for v in colors if v != bg and v not in {grid[0][c] for c in range(w)} and v not in {grid[-1][c] for c in range(w)}), key=lambda v: colors[v], default=None)
    if marker is None:
        marker = min((v for v in colors if v != bg), key=lambda v: colors[v])
    for r, a, b in bars:
        # right half of each bar defines the stream columns
        start = a + (b - a + 1) // 2
        cols = range(start, b + 1)
        rows = range(r + 1, h) if r == 0 else range(0, r)
        for rr in rows:
            for cc in cols:
                out[rr][cc] = 4 if grid[rr][cc] == marker else marker
    return out
